# shinylive::export(appdir = "Aulas/12_pop2/app_endogamia", destdir = "C:/Users/saulo/OneDrive/saulo-chaves.github.io/teaching/shinyapps/app_endogamia")

library(shiny)
library(ggplot2)
library(tidyr)

# ==============================================================================
# INTERFACE DO USUÁRIO (UI)
# ==============================================================================
ui <- fluidPage(
  
  # Título da Aplicação
  titlePanel(
    div(
      style = "display: flex; align-items: center; justify-content: space-between; padding: 10px 0; border-bottom: 2px solid #741821; margin-bottom: 20px;",
      
      # Lado Esquerdo: Título e Autor
      div(
        h3("Genética de Populações II: Endogamia", style = "margin: 0; font-weight: bold; color: #741821;"),
        p("Desenvolvido por ", tags$b("Prof. Saulo Chaves"), " | Laboratório de Ciências de Dados para o Melhoramento de Plantas | ESALQ/USP", 
          style = "margin: 3px 0 0 0; font-size: 14px; color: #741821;")
      ),
      
      # Lado Direito: Logo do Laboratório / Departamento
      tags$a(
        href = "https://saulo-chaves.github.io", target = "_blank",
        tags$img(
          src = "https://saulo-chaves.github.io/assets/img/logolab9.png", # Ou "logo.png" na pasta www
          height = "55px", 
          alt = "Data Science for Plant Breeding"
        )
      )
    )
  ),
  
  tags$head(
    tags$style(HTML("
      /* 1. Títulos, Cabeçalhos e Links */
      h1, h2, h3, h4, h5, h6, .titlePanel {
        color: #741821 !important;
      }
      a {
        color: #741821;
      }
      a:hover {
        color: #4f1016;
      }

      /* 2. Botões Principais (btn-primary) */
      .btn-primary {
        background-color: #741821 !important;
        border-color: #741821 !important;
        color: #ffffff !important;
      }
      .btn-primary:hover, .btn-primary:focus, .btn-primary:active {
        background-color: #4f1016 !important; /* Tom mais escuro ao passar o mouse */
        border-color: #4f1016 !important;
      }

      /* 3. Sliders do Shiny (ionRangeSlider) */
      /* Barra preenchida do slider */
      .irs--shiny .irs-bar {
        background-color: #741821 !important;
        border-top: 1px solid #741821 !important;
        border-bottom: 1px solid #741821 !important;
      }
      /* Balãozinho com o valor numérico acima do slider */
      .irs--shiny .irs-single, 
      .irs--shiny .irs-from, 
      .irs--shiny .irs-to {
        background-color: #741821 !important;
      }
      /* Borda da bolinha/alça de arrastar */
      .irs--shiny .irs-handle {
        border: 3px solid #741821 !important;
      }
    "))
  ),
  
  sidebarLayout(
    sidebarPanel(
      h4("Parâmetros Populacionais"),
      
      # Entrada da Frequência Alélica p
      sliderInput("p", "Frequência do alelo A (p):", 
                  min = 0, max = 1, value = 0.4, step = 0.05),
      
      # Entrada da Taxa de Autofecundação s
      sliderInput("s", "Taxa de Autofecundação (s):", 
                  min = 0, max = 1, value = 0.7, step = 0.05),
      
      # Entrada do Número de Gerações
      sliderInput("n_ger", "Número de Gerações:", 
                  min = 5, max = 50, value = 20, step = 5),
      
      hr(),
      p(strong("Relação do Fis com s (no equilíbrio de Wright):")),
      withMathJax("$$F_{IS} = \\frac{s}{2 - s}$$")
    ),
    
    mainPanel(
      # Indicadores Rápidos (Resumo)
      fluidRow(
        column(4, 
               wellPanel(
                 h5("Frequência de a (q)"),
                 h3(textOutput("val_q"))
               )
        ),
        column(4, 
               wellPanel(
                 h5("Fis no Equilíbrio de Wright"),
                 h3(textOutput("val_fis"))
               )
        ),
        column(4, 
               wellPanel(
                 h5("Heterozigose Final Observada (H)"),
                 h3(textOutput("val_h_final"))
               )
        )
      ),
      
      # Painéis com Abas (Gráfico e Tabela)
      tabsetPanel(
        tabPanel("Gráfico", plotOutput("plot_frequencias", height = "480px")),
        tabPanel("Tabela de Dados", tableOutput("tabela_frequencias"))
      )
    )
  )
)

# ==============================================================================
# LÓGICA DO SERVIDOR (SERVER)
# ==============================================================================
server <- function(input, output, session) {
  
  # 1. Cálculo Reativo do Fis de Equilíbrio
  Fis <- reactive({
    if (input$s == 2) return(1)
    input$s / (2 - input$s)
  })
  
  # 2. Simulação das Frequências Genotípicas ao longo das gerações
  dados_simulados <- reactive({
    p <- input$p
    s <- input$s
    n_ger <- input$n_ger
    
    # Geração 1 (Equilíbrio de Hardy-Weinberg inicial)
    fregen <- data.frame(
      ger = 1,
      D = p^2,
      H = 2 * p * (1 - p),
      R = (1 - p)^2
    )
    
    # Recorrência para as gerações seguintes
    if (n_ger > 1) {
      for (i in 1:(n_ger - 1)) {
        D_ant <- fregen[i, "D"]
        H_ant <- fregen[i, "H"]
        R_ant <- fregen[i, "R"]
        
        fregen <- rbind(
          fregen,
          data.frame(
            ger = i + 1,
            D = (1 - s) * (p^2) + s * (D_ant + (1/4) * H_ant),
            H = 2 * (1 - s) * p * (1 - p) + (1/2) * s * H_ant,
            R = (1 - s) * ((1 - p)^2) + s * (R_ant + (1/4) * H_ant)
          )
        )
      }
    }
    
    return(fregen)
  })
  
  # 3. Output dos Cards de Resumo
  output$val_q <- renderText({
    sprintf("%.2f", 1 - input$p)
  })
  
  output$val_fis <- renderText({
    sprintf("%.4f", Fis())
  })
  
  output$val_h_final <- renderText({
    df <- dados_simulados()
    sprintf("%.4f", tail(df$H, 1))
  })
  
  # 4. Output do Gráfico ggplot2
  output$plot_frequencias <- renderPlot({
    df <- dados_simulados()
    
    # Formatação dos dados para o ggplot (pivoteamento)
    df_long <- df |> 
      pivot_longer(D:R, names_to = "geno", values_to = "freq")
    
    # Rotular os genótipos de forma clara na legenda
    df_long$geno <- factor(
      df_long$geno, 
      levels = c("D", "H", "R"), 
      labels = c("AA (D)", "Aa (H)", "aa (R)")
    )
    
    g <- ggplot(df_long, aes(x = ger, y = freq, color = geno, fill = geno, shape = geno)) + 
      geom_point(size = 3) + 
      geom_line(aes(group = geno), linewidth = 1.2) + 
      theme_bw() + 
      theme(
        text = element_text(size = 20), 
        legend.position = 'top', 
        legend.title = element_blank()
      ) + 
      labs(x = "Geração", y = "Frequência")
    
    
    return(g)
  })
  
  # 5. Output da Tabela de Dados
  output$tabela_frequencias <- renderTable({
    df <- dados_simulados()
    colnames(df) <- c("Geração", "AA (Homozigoto Dominante)", "Aa (Heterozigoto)", "aa (Homozigoto Recessivo)")
    df
  }, digits = 4)
  
}

# Executa o aplicativo Shiny
shinyApp(ui = ui, server = server)
